INSERT INTO camps (name, operator_name, website_url, registration_url, email, phone, street_address, city, state, zip, region, camp_type, primary_categories, secondary_categories, activities, gender_policy, age_min, age_max, grade_min, grade_max, description_short, indoor_outdoor, religious_affiliation, price_min, price_max, price_per_week, price_per, extended_care, transportation, meals_included, financial_aid, refund_policy_summary, special_needs_notes, swim_waterfront_notes, aca_accredited, aca_source_url, season_year, id, slug, location, is_day_camp, is_sleepaway, is_specialty, stem_focus, arts_focus, sports_focus, nature_focus, verification_status, sources, last_reviewed_date, last_updated_date, is_active) VALUES
('Lewiston Recreation Summer Camp', 'City of Lewiston Recreation Department', 'https://lewistonme.myrec.com/info/activities/program_details.aspx?ProgramID=29913', 'https://lewistonme.myrec.com/info/activities/default.aspx', 'recdept@lewistonmaine.gov', '207-513-3005', '65 Central Ave', 'Lewiston', 'ME', '04240', 'Maine', 'day', ARRAY['sports','arts','STEM']::text[], NULL, ARRAY['field games','gym games','arts & crafts','STEM projects','special events','field trips','color battle','talent show','career exploration','whitewater rafting (Teen Extreme overnight)']::text[], NULL, NULL, NULL, 0, 8, 'A city-run day camp at the Lewiston Armory for children entering grades K-8. It runs for 7 weeks, 7:30am-5:30pm, with field and gym games, arts & crafts, STEM projects, special events and field trips. The 6th-8th grade Teen Extreme group goes on an overnight whitewater rafting trip.', NULL, NULL, 225, 1295, 225, 'week', NULL, NULL, TRUE, TRUE, 'You pay a $100 non-refundable deposit when you register, and the balance is due by Friday, June 19. There are no refunds if day plans or field trips change or are cancelled. If a Teen Extreme camper skips the overnight trip, the higher price for that week is not discounted or refunded. Payment plans must be paid off by July 31.', 'There is no trained medical professional on staff. Campers take their own medication, with help from the Summer Camp Lead or a Senior Staff member, and a signed Medical Authorization Form must be on file.', 'Campers pack a towel and swim clothes, and any day can bring sprinkler or water games. On water trips (for example Kennedy Park pool) campers are always with a counselor, at 1 counselor to 5 campers; grades K-2 may go in to their knees and grades 3-8 to their waist. Staff are trained in the camp''s waterfront protocol. The Teen Extreme overnight includes pool access and whitewater rafting with Adventurebound in Caratunk, ME.', NULL, NULL, 2026, '616097cd-6c79-5477-abc1-2089d6624e9b', 'lewiston-recreation-summer-camp-lewiston', ST_GeogFromText('SRID=4326;POINT(-70.1721 44.0895)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://lewistonme.myrec.com/documents/k2_camp_calendar.pdf','https://lewistonme.myrec.com/documents/summer_camp_family_handbook_2026.pdf','https://lewistonme.myrec.com/info/activities/program_details.aspx?ProgramID=29913']::text[], '2026-11-13', '2026-11-13', TRUE),
('Pine Tree Camp', 'Pine Tree Society', 'https://pinetreesociety.org/camp-home/', NULL, 'ptcamp@pinetreesociety.org', '(207) 386-5990', '114 Pine Tree Camp Road', 'Rome', 'ME', '04963', 'Maine', 'sleepaway', ARRAY['special_needs','nature','sports','arts','performing_arts']::text[], NULL, ARRAY['Boating and paddling','Swimming','Fishing','Nature trails','Gardening','Farm animals','Adaptive sports','Adaptive biking','Accessible playground','Accessible tent site','Archery','Music','Drama','Arts and Crafts','Cooking']::text[], NULL, 5, NULL, NULL, NULL, 'A fully accessible 285-acre camp in Maine''s Belgrade Lakes Region for children and adults with developmental and physical disabilities, with a 3:1 camper-to-counselor ratio. Programs range from day-long experiences to week-long overnight sessions for children, adults and families.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, 'Every camper must have a developmental or physical disability. The camp says it accommodates individual campers'' needs so they can try any activity, keeps a 3:1 camper-to-counselor ratio, and has nurses on site 24 hours a day during overnight sessions to give medication and medical care.', 'There is an accessible waterfront on North Pond with an aquatics program that teaches swimming techniques suited to each camper. Boating, paddling and fishing from pontoon boats and a fishing dock are also offered.', NULL, NULL, 2026, '6c89ddb7-d3a7-5fb1-aeca-ecd609f5a0a6', 'pine-tree-camp-rome', ST_GeogFromText('SRID=4326;POINT(-69.8931 44.5705)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://pinetreesociety.org/camp-home/','https://pinetreesociety.org/camp-home/childrens-overnight-camp/','https://pinetreesociety.org/camp-home/program-options/']::text[], '2026-11-13', '2026-11-13', TRUE),
('SailMaine Youth Summer Programs', 'SailMaine', 'https://www.sailmaine.org/youth-summer-camp', 'https://sailmaine.campmanagement.com/p/request_for_info_m.php?action=enroll', NULL, '(207) 772-7245', 'Amethyst Lot Park (end of Commercial St/Thames St)', 'Portland', 'ME', '04101', 'Maine', 'specialty', ARRAY['sports','nature']::text[], NULL, ARRAY['Sailing','Sailboat racing','Trips to local islands and Fort Gorges','Navigation and seamanship','Spinnaker and trapeze work','Powerboat instruction (Apprentice Program)','Instructor apprenticeship']::text[], NULL, 5, 17, NULL, NULL, 'Sailing classes for ages 5–17 on Casco Bay in Portland, from beginner classes to Opti and 420 racing teams. Most programs run in 2-week sessions with morning, afternoon or full-day options. A 1-week program also runs at Centerboard Yacht Club in South Portland.', NULL, NULL, 289, 890, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, 'Programs take place on the water in Casco Bay (Portland) using J/22s, Frosties, Optimists, 420s and Lasers. Some classes have weight limits: Opti classes 110 lbs or less, 420 classes over 100 lbs. Swim test and life jacket rules are not stated.', NULL, NULL, 2026, '13932f50-fb48-5976-a1a0-227bff0a0937', 'sailmaine-youth-summer-programs-portland', ST_GeogFromText('SRID=4326;POINT(-70.2568 43.6591)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://www.sailmaine.org/youth-summer-camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Day Camp (Grades 1-5)', 'Bath Area Family YMCA', 'https://bathymca.org/daycamp/', 'https://bathymca.org/register/', 'kayla@bathymca.org', '(207) 443-4112 x39', '303 Centre Street', 'Bath', 'ME', '04530', 'Maine', 'day', ARRAY['sports','arts']::text[], NULL, ARRAY['sports','teamwork and skill building','arts and creative expression','outdoor games','pool time/free swim','beach trips','weekly excursions','special events','optional swim lessons (extra cost)','optional sport classes (extra cost)']::text[], NULL, NULL, NULL, 1, 5, 'A general summer day camp at the Bath YMCA for children entering grades 1-5 in fall 2027. Activities include sports, arts, outdoor games, pool time, beach trips and weekly excursions.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, TRUE, TRUE, 'There is a $35 registration fee per camper, charged once. It cannot be refunded or transferred. A $25 deposit per week per camper holds each week''s spot. Deposits cannot be refunded or transferred, and they count toward tuition. Fees are due within 7 days of enrollment confirmation, and full payment is due the Friday before a session starts.', NULL, 'Campers get pool time/free swim throughout camp, plus beach trips. Structured swim lessons with certified instructors cost extra and run 8:00-9:00AM, Monday-Friday, for that week''s campers only. Financial aid is available for lessons. The Y has a separate Swim Test Policy page.', NULL, NULL, 2027, '135b0740-4002-50de-9337-adcb634fce67', 'summer-day-camp-grades-1-5-bath', ST_GeogFromText('SRID=4326;POINT(-69.8472 43.9325)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://bathymca.org/daycamp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Tripp Lake Camp', NULL, 'https://www.tripplakecamp.com/', NULL, 'info@tripplakecamp.com', '207-998-4347', '132 Tripp Lake Camp Rd.', 'Poland', 'ME', '04274', 'Maine', 'sleepaway', ARRAY['sports','arts','nature','performing_arts']::text[], NULL, ARRAY['Arts (art shops)','Land sports','Waterfront','Outdoor living program','Equestrian','Theatre','Special events']::text[], 'girls', 7, 16, NULL, NULL, 'Traditional full-summer overnight camp for girls ages 7-16 on a lake in Poland, Maine, operating since 1911. Campers stay for the full season, with activities in arts, land sports, waterfront, outdoor living, horseback riding and theatre.', NULL, NULL, 18200, 18200, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The camp has a mile-long waterfront on Tripp Lake. Campers swim nearly every day, with a scheduled swim period for each age group plus free swim, and move up through colored swim caps as they learn skills. Canoeing, kayaking, sailing, waterskiing and wakeboarding are taught, starting with safety and technique.', NULL, NULL, 2027, '8b0ac424-6499-5384-8d31-a53a543aac28', 'tripp-lake-camp-poland', ST_GeogFromText('SRID=4326;POINT(-70.3936 44.0481)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.tripplakecamp.com/activities/waterfront/','https://www.tripplakecamp.com/contact/','https://www.tripplakecamp.com/dates-tuition/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Windham Parks & Recreation Summer Day Camp', 'Town of Windham Parks & Recreation', 'https://www.windhammaine.us/878/Summer-Day-Camp', 'https://www.rec.us/organizations/town-of-windham', 'parks&recreation@windhammaine.us', '207-892-1905', '8 School Road', 'Windham', 'ME', '04062', 'Maine', 'day', ARRAY['sports','arts']::text[], NULL, ARRAY['field trips','special events','arts and crafts','sports and games','field games','water play','whitewater rafting overnight (Adventure Camp)','community service days (Adventure Camp)']::text[], NULL, NULL, NULL, 1, 8, 'A 7-week town-run summer day camp for grades 1-8, 7:30am-5:30pm, based at Windham High School and Windham Middle School. Campers are split into Discover Camp (grades 1-3), Ranger Camp (grades 4-5) and Adventure Camp (grades 6-8), with field trips, special events, arts and crafts, sports and games. Adventure Camp ends with an overnight whitewater rafting trip.', NULL, NULL, 255, 255, 255, 'week', NULL, NULL, FALSE, TRUE, NULL, NULL, 'Field trips include lakes and the ocean, and staff go into the water with campers. Grades 1-3 may go waist deep in lakes and knee deep in the ocean; grades 4-5 chest deep in lakes and waist deep in the ocean; neither group ever goes over their heads. Grades 6-8 must tread water for 2 minutes to go over their heads in lakes, in groups of 3 with an adult. Tell the camp director if your child can''t swim.', NULL, NULL, 2026, '119fd25c-a36c-5a82-b41c-969649bf9f54', 'windham-parks-and-recreation-summer-day-camp-windham', ST_GeogFromText('SRID=4326;POINT(-70.4053 43.7947)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.windhammaine.us/165/Youth-Family-Programs','https://www.windhammaine.us/878/Summer-Day-Camp','https://www.windhammaine.us/DocumentCenter/View/12175/2026-Parent-and-Camper-Handbook']::text[], '2026-11-13', '2026-11-13', TRUE),
('YMCA Camp of Maine', 'YMCA Camp Of Maine', 'https://www.maineycamp.org/', 'https://maineycamp.campintouch.com/ui/forms/application/camper/App', 'info@maineycamp.org', '207-395-4200', '305 Winthrop Center Rd', 'Winthrop', 'ME', '04364', 'Maine', 'sleepaway', ARRAY['sports','arts','outdoor','nature']::text[], NULL, ARRAY['Canoeing','Kayaking','Sailing','Paddle boarding','Snorkeling','Swim lessons','Free swim','Volleyball','Basketball','Tennis','Soccer','Yoga','Archery','Axe throwing','Challenge course','Overnight camping','Fishing','Outdoor cooking','Musical theater','Dance','Painting and drawing','Guitar and ukulele','Pottery/ceramics']::text[], 'coed', NULL, NULL, NULL, NULL, 'Overnight YMCA camp founded in 1915 on the shores of Lake Cobbossee in Winthrop, Maine, offering one- and two-week sessions for boys and girls. Programs listed include Traditional Camp, Explorer''s Camp and a LIT/CIT program.', NULL, NULL, 534, 2642, NULL, 'session', NULL, NULL, TRUE, TRUE, 'Balances are due June 1. The deposit ($125 a week, $250 a two-week session, per camper) is never refunded. Cancel more than 30 days before your session and you get 25% of the full tuition back; within 30 days there is no refund.', NULL, 'The camp is on Lake Cobbossee. Certified lifeguards run the waterfront, which offers canoeing, kayaking, sailing, paddle boarding, snorkeling, water games and free swim. Younger cabins (Kennebec Porch and Cobbossee) are all assigned a period of swim lessons.', NULL, NULL, 2027, 'c5840250-9009-591a-9817-c0d6183987fb', 'ymca-camp-of-maine-winthrop', ST_GeogFromText('SRID=4326;POINT(-69.9631 44.31)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.maineycamp.org/','https://www.maineycamp.org/camp-life/activities','https://www.maineycamp.org/programs/dates-fees']::text[], '2026-11-13', '2026-11-13', TRUE),
('Portland Stage Summer Theater Camps', 'Portland Stage', 'https://www.portlandstage.org/education/summer-camps/', 'https://form.jotform.com/250014604795050', NULL, '207-774-0465', '25A Forest Ave', 'Portland', 'ME', '04101', 'Maine', 'specialty', ARRAY['performing_arts']::text[], NULL, ARRAY['Acting','Theater','Movement','Improv','Shakespeare','Open studio performance']::text[], NULL, NULL, NULL, 0, 12, 'Week-long theater day camps (9 am–3 pm) for rising K–12th graders at Portland Stage, each themed around a book, play or style such as improv or Shakespeare. Professional actors, directors and artisans teach the camps, and each week ends with an open studio performance for families.', NULL, NULL, 315, 390, 390, 'week', NULL, NULL, NULL, TRUE, 'Full refund if you cancel more than two months before the first day, 50% refund between two months and one month before, and no refund less than one month before. If Portland Stage cancels a program for low enrollment, it tells families two weeks ahead and gives a full refund.', NULL, NULL, NULL, NULL, 2026, '9726ba95-49b9-510a-a576-a7fe301821b9', 'portland-stage-summer-theater-camps-portland', ST_GeogFromText('SRID=4326;POINT(-70.2568 43.6591)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.portlandstage.org/education/summer-camps/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Scarborough Summer Day Camp', 'Scarborough Community Services (Town of Scarborough)', 'https://www.scarboroughmaine.org/departments/community-services/child-care/summer-day-camp', 'https://mescarboroughweb.myvscloud.com/webtrac/web/search.html?display=detail&module=AR&primarycode=K58W5D', 'comserv@scarboroughmaine.org', '(207) 730-4150', NULL, 'Scarborough', 'ME', '04070', 'Maine', 'day', ARRAY['arts','sports']::text[], NULL, ARRAY['Art','Gym activities','Theme programming','Field trips']::text[], NULL, NULL, NULL, 0, 6, 'A town-run day camp for Scarborough resident children entering grades K–6, held at Wentworth School. You sign up for the whole 7-week summer at once, and an optional Week 8 can be added. Campers do art, gym, themed programs and field trips.', NULL, NULL, 1650, 1750, NULL, NULL, TRUE, NULL, NULL, NULL, 'The 7-week program is sold as one unit. Single weeks can''t be dropped; withdrawing means dropping all seven weeks. The page gives no refund terms.', NULL, NULL, NULL, NULL, 2026, '56b09de4-dc6c-5a87-837d-e7593b41b27d', 'scarborough-summer-day-camp-scarborough', ST_GeogFromText('SRID=4326;POINT(-70.3342 43.5712)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.scarboroughmaine.org/departments/community-services/child-care/summer-day-camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Winona Camps for Boys', NULL, 'https://winonacamps.com/', 'https://winonacamps.campintouch.com/ui/forms/application/camper/App', 'information@winonacamps.com', '(207) 647-3721', '35 Winona Road', 'Bridgton', 'ME', '04009', 'Maine', 'sleepaway', ARRAY['nature','sports']::text[], NULL, ARRAY['Outdoor living skills','Canoe and mountain trips','Swimming','Sailing','Kayaking','Rock climbing','Archery','Riflery','Lacrosse','Tennis','Arts and crafts','Farm and garden']::text[], 'boys', 7, 15, NULL, NULL, 'A traditional boys'' sleepaway camp on Moose Pond in Bridgton, founded in 1908, for boys 7 to 15. Campers live in canvas tents, learn outdoor living skills and go on canoe and mountain trips, plus activities like sailing, rock climbing, kayaking and lacrosse. Full season or either half.', NULL, NULL, 8200, 11800, NULL, 'session', NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, '040830e4-3c8c-5987-a7de-d7b2524a515a', 'winona-camps-for-boys-bridgton', ST_GeogFromText('SRID=4326;POINT(-70.7433 44.0475)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://winonacamps.com/','https://winonacamps.com/welcome-campers/activities-trips/','https://winonacamps.com/welcome-campers/units-age-groups/','https://winonacamps.com/welcome-parents/dates-fees-forms/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Maine Audubon Day Camps', 'Maine Audubon', 'https://maineaudubon.org/education/day-camps/', NULL, NULL, '207.781.2330', '20 Gilsland Farm Road', 'Falmouth', 'ME', '04105', 'Maine', 'day', ARRAY['nature']::text[], NULL, NULL, NULL, 3, NULL, NULL, 4, 'Maine Audubon runs nature day camps at Gilsland Farm Audubon Center in Falmouth (Greater Portland) and Fields Pond Audubon Center in Holden (Greater Bangor). It offers summer camps and February/April vacation camps for preschool and elementary-age children.', NULL, NULL, 300, 415, 415, 'week', NULL, NULL, NULL, TRUE, 'Summer camp: full refund if Maine Audubon cancels the session. If you cancel before June 1, you get a refund minus a $30 processing fee per registration. No refunds for cancellations after June 1. Vacation camp: no refunds within 14 days of the start date. Cancellations more than 14 days ahead are refunded minus a $30 fee. COVID-related cancellations are refunded minus a $30 fee.', NULL, NULL, NULL, NULL, 2026, '176dacfc-179f-54aa-ac8f-e9ddce3febf0', 'maine-audubon-day-camps-falmouth', ST_GeogFromText('SRID=4326;POINT(-70.2772 43.7405)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://maineaudubon.org/education/day-camps/','https://maineaudubon.org/wp-content/uploads/2026-Gilsland-Farm-Summer-Camp-one-pager.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('New England Music Camp', 'Snow Pond Center for the Arts', 'https://nemc.org/', 'https://nemc.org/register/', 'info@nemc.org', '(207) 465-3025', '8 Goldenrod Lane', 'Sidney', 'ME', '04330', 'Maine', 'specialty', ARRAY['performing_arts']::text[], NULL, ARRAY['Music','Chamber music','Composition','Classical voice','Musical theatre']::text[], NULL, 9, 18, NULL, NULL, 'A music camp in Sidney, Maine, with three two-week sessions for students ages 9-18 (Session 1) or 11-18 (Sessions 2 and 3). Intensives in chamber music, composition, classical voice and musical theatre are offered in specific sessions.', NULL, NULL, 3900, 9600, NULL, 'session', NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, 'c8ddcec1-8df4-5916-b3f1-23c5cc941f88', 'new-england-music-camp-sidney', ST_GeogFromText('SRID=4326;POINT(-69.7557 44.4382)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://nemc.org/tuition-dates/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Robin Hood Camp', NULL, 'https://www.robinhoodcamp.com', 'https://robinhoodmaine.campintouch.com/ui/forms/application/camper/App', 'robinhood@robinhoodcamp.com', '207-359-8313', '70 Robin Hood Road (P.O. Box 189)', 'Brooksville', 'ME', '04617', 'Maine', 'sleepaway', ARRAY['sports','arts','performing_arts']::text[], NULL, ARRAY['Individual sports','Team sports','Waterfront','Indoor activities','Arts','Music','Performing arts','Trips and excursions','Golf','Tennis','Squash','Soccer','Horseback riding','Wakeboarding/waterskiing/wakesurfing']::text[], 'coed', NULL, 17, NULL, NULL, 'Overnight summer camp in Brooksville, Maine, between a freshwater lake and the ocean, with more than 35 daily activities. Sessions run from two to seven weeks between June 27 and August 15, 2027.', NULL, NULL, 6615, 17515, NULL, NULL, NULL, TRUE, NULL, NULL, 'The $1,000 registration fee is fully refundable until January 1, 2027. Tuition is fully refundable until April 1, 2027. After that there are no refunds for withdrawals or shortened stays (illness, homesickness, behavior dismissal), and no refunds for travel restrictions. The camp recommends tuition protection insurance (TravMark, 1-833-297-2258).', NULL, NULL, NULL, NULL, 2027, 'f9cb703b-e8a1-5a27-bee5-c834b5a01039', 'robin-hood-camp-brooksville', ST_GeogFromText('SRID=4326;POINT(-68.7593 44.3512)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.robinhoodcamp.com/maine-summer-camp-dates-rates/','https://www.robinhoodcamp.com/maine-summer-camp-programs/summer-camp-programs-all-ages/','https://www.robinhoodcamp.com/summer-camp-faqs/']::text[], '2026-11-13', '2026-11-13', TRUE),
('West End House Camp', 'West End House Camp', 'https://westendhousecamp.org/', 'https://westend.campintouch.com/ui/forms/application/camper/App', 'info@westendhousecamp.org', '617-721-4316', '294 Road Between the Ponds', 'Parsonsfield', 'ME', '04047', 'Maine', 'sleepaway', ARRAY['sports','STEM']::text[], NULL, ARRAY['Team sports','Water activities','STEM experiments','Chess tournaments','Large group competitions']::text[], 'boys', 7, 15, NULL, NULL, 'A non-profit summer camp for boys in Parsonsfield, Maine. Boys take part in team sports, water activities, STEM experiments, chess tournaments and large group competitions. Sessions run 2, 3, 4 or 7 weeks.', NULL, NULL, 3295, 11395, NULL, 'session', NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, 'd1e92a9f-4644-5fd5-a931-7eabd904b4ec', 'west-end-house-camp-parsonsfield', ST_GeogFromText('SRID=4326;POINT(-70.894 43.7334)'), FALSE, TRUE, FALSE, TRUE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://westendhousecamp.org/camp-life/','https://westendhousecamp.org/sessions/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Wohelo Camps', 'Wohelo Camps', 'https://wohelo.com/', NULL, 'wohelo@wohelo.com', '207-655-4739', '25 Gulick Road', 'Raymond', 'ME', '04071', 'Maine', 'sleepaway', NULL, NULL, NULL, 'girls', 6, 15, NULL, NULL, 'Wohelo is an overnight camp for girls in Raymond, Maine, run as two camps: Little Wohelo (ages 6-12) and Sebago Wohelo (ages 12-15). The camp prefers the full seven-week season. It also offers half sessions for first-time campers and a one-week Peep Week.', NULL, NULL, 2500, 13200, NULL, 'session', NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, '729c8a39-049f-5288-9b1f-6a8f042d001a', 'wohelo-camps-raymond', ST_GeogFromText('SRID=4326;POINT(-70.4685 43.9176)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://wohelo.com/apply-for-a-wohelo-campership/','https://wohelo.com/dates-tuition/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Maine Discovery Museum Summer Camp', 'Maine Discovery Museum', 'https://www.mainediscoverymuseum.org/summer-camp-2026', NULL, 'info@mainediscoverymuseum.org', '(207) 262-7200', '74 Main Street', 'Bangor', 'ME', '04401', 'Maine', 'day', ARRAY['STEM','nature','arts']::text[], NULL, ARRAY['Space science and rocketry','Engineering','Chemistry and physics experiments','Robotics and coding','Archaeology and fossil casting','Gardening and soil science','Marine biology','Science-based art','Nature hikes and ecology']::text[], NULL, NULL, NULL, 1, 6, 'Weekly hands-on STEM day camps at the Maine Discovery Museum in Bangor for children entering grades 1–6. Each week has a theme, such as space, robotics, or oceans. One outdoor art and ecology week is held at Caribou Bog Outdoor Center in Orono.', NULL, NULL, 350, 350, 350, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '3e596a57-f1e5-5dd2-87f6-41c411b7fc90', 'maine-discovery-museum-summer-camp-bangor', ST_GeogFromText('SRID=4326;POINT(-68.7888 44.8296)'), TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, 'unverified', ARRAY['https://www.mainediscoverymuseum.org/summer-camp-2026']::text[], '2026-11-13', '2026-11-13', TRUE),
('Pine Island Camp', 'Pine Island Camp', 'https://pineisland.org/', 'https://pineisland.campintouch.com/ui/forms/application/camper/App', 'atoole@pineisland.org', '(207) 465-3031', '234 Pine Island Road', 'Belgrade', 'ME', '04917', 'Maine', 'sleepaway', ARRAY['nature','sports']::text[], NULL, ARRAY['Swimming','Rowing','Sailing','Boating','Fishing','Hiking','Wilderness/camping trips','Shelter building','Basketball','Dustball','Campfire skits, music and storytelling']::text[], 'boys', 9, 15, NULL, NULL, 'A six-week, single-session overnight camp for boys ages 9 to 15 on an island in Great Pond in the Belgrade Lakes of central Maine. Campers live without electricity or phones, pick their own daily activities and wilderness trips, and write letters home.', NULL, NULL, 12500, 15600, NULL, NULL, NULL, NULL, TRUE, TRUE, NULL, NULL, 'The camp is on an island in Great Pond. Swimming follows Red Cross standards, from beginner to life-saving; every boy must reach at least beginner rank. There are two general swim periods a day with three lifeguards on duty, life jackets are required for all boating, and waterfront staff arrive with WSI and Lifeguard certification before in-camp training.', NULL, NULL, 2027, 'ebb634e5-0f86-573b-91a1-1391ed045a62', 'pine-island-camp-belgrade', ST_GeogFromText('SRID=4326;POINT(-69.8376 44.5231)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://pineisland.org/about/','https://pineisland.org/camp-life/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Sail Kids For Free (SKFF)', 'Sail, Power & Steam Museum', 'https://www.sailpowersteammuseum.org/sail-kids-for-free-skff', NULL, NULL, '207-701-7627', '75 Mechanic St.', 'Rockland', 'ME', '04841', 'Maine', 'specialty', ARRAY['sailing','sports']::text[], NULL, ARRAY['Sailing (Optimist Prams)','Rigging','Line handling','Docking','Sail trim','Capsize recovery','Regatta']::text[], NULL, 8, 14, NULL, NULL, 'A free, week-long beginner sailing program for ages 8–14. Kids sail Optimist Prams in the harbor from 9AM to 12PM, Monday to Friday, and the week ends with a friendly regatta.', NULL, NULL, 0, 0, 0, 'week', NULL, NULL, NULL, NULL, NULL, NULL, 'Sailing happens in the harbor on Optimist Prams. Kids practise capsizing safely and righting their boats.', NULL, NULL, 2027, 'fdbf13e3-7f34-5587-bc31-c90711794bce', 'sail-kids-for-free-skff-rockland', ST_GeogFromText('SRID=4326;POINT(-69.1305 44.1239)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=75+Mechanic+St.&city=Rockland&state=ME&benchmark=Public_AR_Current&format=html','https://www.sailpowersteammuseum.org/sail-kids-for-free-skff']::text[], '2026-11-13', '2026-11-13', TRUE),
('Slovenski Camps', 'Slovenski Family', 'https://www.slovenskicamps.com', NULL, 'yourfriends@slovenskicamps.com', '(207) 641-7566', '25 David Plummer Rd', 'Raymond', 'ME', '04071', 'Maine', 'sleepaway', ARRAY['sports','nature','technology']::text[], NULL, ARRAY['swimming','dodgeball','capture the flag','singing','dancing','paddling','sailing','wind-surfing','pole vault','cross-country running','robotics','evening campfire','reading classics','poetry memorization']::text[], 'coed', NULL, NULL, NULL, NULL, 'A coed overnight camp in Raymond, Maine, with weekly Saturday-to-Saturday sessions. Several programs run side by side: Athena Girls Camp, Camp Hawthorne for boys, dodgeball, pole vault, middle school cross-country, swim and robotics. Campers share meals, free time and an evening campfire, and phones and screens are not allowed.', NULL, NULL, 900, 1580, 1580, 'week', NULL, NULL, NULL, NULL, NULL, NULL, 'The camp is on Panther Pond. The Speed Swim program trains in the pond. Sailing and wind-surfing are run by Paul Slovenski, who the camp says "has years of experience supervising waterfront activities to ensure maximum safety."', NULL, NULL, 2027, 'c690b41e-ec30-5bbb-bb11-933a73ef324c', 'slovenski-camps-raymond', ST_GeogFromText('SRID=4326;POINT(-70.4685 43.9176)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://www.slovenskicamps.com/our-camps/']::text[], '2026-11-13', '2026-11-13', TRUE),
('University of Maine 4-H Camp & Learning Center at Greenland Point', 'University of Maine Cooperative Extension', 'https://extension.umaine.edu/greenland-point/summer-camp/', 'https://extension.umaine.edu/greenland-point/summer-camp/registration-link/', 'extension.bryantpond@maine.edu', '207.665.2068', '89 UOM Forestry Road', 'Princeton', 'ME', '04668', 'Maine', 'sleepaway', ARRAY['nature','outdoor','arts']::text[], NULL, ARRAY['Swimming','Canoeing','Fishing','Archery','Wilderness survival skills','Nature exploration','Outdoor adventures','Thursday evening campfire with skits, songs and stories']::text[], NULL, 5, 17, NULL, NULL, 'A University of Maine 4-H camp on a 64-acre wooded peninsula on Long Lake in Princeton, Maine. Overnight programs run Sunday to Friday for ages 7 to 17, including fishing, hunter safety, naturalist, art, warden camp, woodscraft, leadership and counselor in training, plus a four-day day camp for ages 5 to 9.', NULL, NULL, 325, 1650, 750, NULL, NULL, NULL, TRUE, TRUE, 'A $50 deposit is due at registration. Written cancellations at least 28 days before the program get a refund minus the $50 deposit; later cancellations get no refund. No refunds for illness, injury, homesickness, behavior, weather or leaving early once the program starts. Full payment is due 28 days before the start.', NULL, 'The camp sits on Long Lake with an extensive waterfront for swimming and canoeing. The camp''s FAQ says all swimming activities are overseen by certified lifeguards.', NULL, NULL, 2027, '9f87d6d3-8d06-58cb-8134-0a9b1c2342d7', 'university-of-maine-4-h-camp-and-learning-center-at-greenland-point', ST_GeogFromText('SRID=4326;POINT(-67.527 45.1446)'), FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, TRUE, 'unverified', ARRAY['https://extension.umaine.edu/greenland-point/about-us/contact-us/','https://extension.umaine.edu/greenland-point/summer-camp/','https://extension.umaine.edu/greenland-point/summer-camp/aqua-adventure-ages-7-10/','https://extension.umaine.edu/greenland-point/summer-camp/art-exploration-7-10/','https://extension.umaine.edu/greenland-point/summer-camp/arts-adventures-ages-10-13/','https://extension.umaine.edu/greenland-point/summer-camp/counselor-in-training-ages-16-17/','https://extension.umaine.edu/greenland-point/summer-camp/day-camp-ages-5-9/','https://extension.umaine.edu/greenland-point/summer-camp/fishing-camp-ages-10-13/','https://extension.umaine.edu/greenland-point/summer-camp/frequently-asked-questions/','https://extension.umaine.edu/greenland-point/summer-camp/hooked-on-bass/','https://extension.umaine.edu/greenland-point/summer-camp/hunter-safety-firearm-atv-ages-10-13/','https://extension.umaine.edu/greenland-point/summer-camp/junior-naturalist-program-ages-7-10/','https://extension.umaine.edu/greenland-point/summer-camp/long-lake-leadership/','https://extension.umaine.edu/greenland-point/summer-camp/naturalist-program-ages-10-13/','https://extension.umaine.edu/greenland-point/summer-camp/warden-camp/','https://extension.umaine.edu/greenland-point/summer-camp/wilderness-explorers-ages-7-10/','https://extension.umaine.edu/greenland-point/summer-camp/wilderness-survival-ages-10-13/','https://extension.umaine.edu/greenland-point/summer-camp/woodscraft-ages-12-14/']::text[], '2026-11-13', '2026-11-13', TRUE),
('White Pine Camps', 'White Pine Programs', 'https://whitepineprograms.org/summercamp-outdoorcamp-nature-camp/', NULL, 'info@whitepineprograms.org', '207-361-1911', NULL, 'York', 'ME', '03909', 'Maine', 'day', ARRAY['nature']::text[], NULL, ARRAY['sit spots','nature journaling','shelter building','bushcraft','wood carving','cordage making','weaving','map & compass','wild edibles identification','forest games','stories and songs','hiking','backpacking','overnight camping','stewardship projects']::text[], NULL, 4, 17, NULL, NULL, 'An all-outdoor nature camp in York, Maine for ages 4–17, with weekly day programs at Coastal Ridge Elementary School, a leadership week with a Thursday overnight, a traveling camp, a counselor-in-training program, and backcountry expeditions for teens. Activities center on bushcraft, shelter building, nature journaling, map and compass, and community-building.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, TRUE, 'Every session has a non-refundable, non-transferable $50 deposit ($100 for expeditions); families who are not approved for financial aid get the deposit back in full. A $50 administrative fee applies to any cancellation. Cancelling 60 to 31 days before the start may get 50% of tuition back, minus the fee; cancelling 2 weeks or less before gets no refund. Week transfers are not possible within 2 weeks of the start. If the camp and family agree White Pine is not the right fit for a child with special needs, the camp honors a full cancellation.', 'Many campers have IEPs or 504 plans. Families should call 207-361-1911 or email samm@whitepineprograms.org as soon as they register to talk about fit. The camp cannot provide one-on-one support, but outside aides (for example, a school-provided ed-tech) may come with the child. Behavior that puts others at risk may mean a child cannot continue in the program.', NULL, NULL, NULL, 2027, 'f85a5e72-a01e-5b11-aaba-e48e91dc23fb', 'white-pine-camps-white-pine-programs-summer-camp-york', ST_GeogFromText('SRID=4326;POINT(-70.591 43.1655)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://whitepineprograms.org/summercamp-outdoorcamp-nature-camp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Y Summer Camp at OLEC', 'YMCA of Auburn-Lewiston', 'https://alymca.org/programs/summer-camp/', 'https://operations.daxko.com/Online/2099/ProgramsV2/Home.mvc', 'afuller@alymca.org', '207-795-4095 ext. 208', '151 Stetson Road', 'Auburn', 'ME', '04210', 'Maine', 'day', ARRAY['nature','sports','arts']::text[], NULL, ARRAY['swimming (pool)','archery','basketball','gaga','hiking','field games','campfires','arts & crafts','music','guest speakers','themed weeks','nature exploration']::text[], NULL, 5, NULL, NULL, 8, 'A weekly-themed summer camp run by the YMCA of Auburn-Lewiston at its Outdoor Learning and Education Center (OLEC) in Auburn, Maine, for kids from age 5 through grade 8. Campers use an outdoor field, basketball court, pool, archery range, gaga ring, fire pits and hiking trails, and also do arts & crafts and music.', NULL, NULL, 215, 235, NULL, NULL, TRUE, NULL, NULL, TRUE, NULL, NULL, 'OLEC has a pool. Every camper is swim tested, swim instruction, lessons and water safety are offered every session, and certified lifeguards are on staff.', NULL, NULL, 2026, 'f351b2f4-575a-5305-a829-2ba46e906b63', 'y-summer-camp-at-olec-auburn', ST_GeogFromText('SRID=4326;POINT(-70.2496 44.0845)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://alymca.org/programs/summer-camp/','https://alymca.org/wp-content/uploads/2026/02/Y-Summer-Camp-2026-Family-Info-Packet-01.pdf','https://geocoding.geo.census.gov/geocoder/locations/address?street=151+Stetson+Road&city=Auburn&state=ME&benchmark=Public_AR_Current&format=html']::text[], '2026-11-13', '2026-11-13', TRUE)
